def match_parens(lst):
    open_count = lst.count('(')
    close_count = lst.count(')')

    if open_count != close_count:
        return 'No'

    stack = []
    for paren in lst:
        if paren == '(':
            stack.append(paren)
        else:
            if not stack:
                return 'No'
            stack.pop()

    if not stack:
        return 'Yes'
    else:
